# Dotstory SEO + GEO update (includes the earlier content update + Services page, so it is safe to run on its own).
# Put this file in your site folder (the one containing index.html and the _nuxt folder), then run:
#   powershell -ExecutionPolicy Bypass -File .\apply-dotstory-seo-update.ps1
# -SiteUrl  the public address the site lives at (used in canonical tags, sitemap, schema). Default: https://dotstory.io
#           Example while testing on Vercel:  -SiteUrl https://ovclone.vercel.app
# -Push     also commit and push to git afterwards.
param([string]$SiteUrl = 'https://dotstory.io', [switch]$Push)
$ErrorActionPreference = 'Stop'
$SiteUrl = $SiteUrl.TrimEnd('/')
if ($SiteUrl -notmatch '^https?://[^/\s]+$') { Write-Host "SiteUrl must look like https://dotstory.io (no path)." -ForegroundColor Red; exit 1 }
$root = Split-Path -Parent $MyInvocation.MyCommand.Path
if (-not (Test-Path (Join-Path $root 'index.html')) -or -not (Test-Path (Join-Path $root '_nuxt'))) {
  Write-Host "Run this from your site folder (it must contain index.html and the _nuxt folder)." -ForegroundColor Red
  exit 1
}
$backup = Join-Path $root ('_backup_before_seo_update_' + (Get-Date -Format 'yyyyMMdd_HHmmss'))
$files = @(
  @{ Path='404.html'; Sha='6d8aa5a75518c5b7bfb9f657a6539eb5ffb749b1d719ab5ad115bf553dc9770f'; Data='' }
  @{ Path='_nuxt/BAugoq4T.js'; Sha='1cdc39fbb0fbcf989d095bfc2247d1a5143d0866bcf6733ff35c81253f4dc10c'; Data='' }
  @{ Path='_nuxt/CPjIKiRm.js'; Sha='b5e34941fa3effd6d678297af8988dc54483ffb6011f1dcaa5b58cb348838d91'; Data='' }
  @{ Path='_nuxt/DC_P54Ec.js'; Sha='cb9a9f5c035b35c634bdaea2e196d5d164508788a9c3761fa87ba1b22f2a90f3'; Data='' }
  @{ Path='_nuxt/t9sCvZVC.js'; Sha='900d53195d6ab5bade7f4817cc1099a38b8f676db1972a47e0d40f5a21b668a9'; Data='' }
  @{ Path='about'; Sha='687ae5b7cb64550131859938fecb9b073f5c7b4af865a876f152293d4008d4ab'; Data='' }
  @{ Path='contact'; Sha='ca03fc8cc21fadc262d79ac1f498458704b6d4c431bddd0b3d511bd876f01097'; Data='' }
  @{ Path='favicon.svg'; Sha='4824a2fb761e641622f0f3e9c403a633111d6c6cef9d589fbe519beab774d6a8'; Data='H4sIACxB52oC/z3N2wrCMAwG4HufIsT7td1EQdpe+Caj9gTVSVeW+fbLHBgCf0g+iJ6XCOurvGeDqbXPXQgi6mjophpFL6UULBCW7OkxrQYlSLheuNHq6l0Dys+WDPICks8xtWOubBVnyKUYPKugRnVDYbXL1RUPju9Dj+C+R1bm6s/Dr3a+v7enDYBHJgKnAAAA' }
  @{ Path='index.html'; Sha='b941ee9358f2e1489a15520eef87ed021e8ac13cd072e2e4a4c2933162d3d1ce'; Data='' }
  @{ Path='legal'; Sha='149eb1387272154880437939b1b6385411c053bdbfef8a11a1bf07f15ec7a3b6'; Data='' }
  @{ Path='llms.txt'; Sha='1d30657240346e92da1bbb622ef4a3f3af3e8da5015f25a53eb5dbcfd173ddc4'; Data='' }
  @{ Path='robots.txt'; Sha='b2b96f00615b081b22ea7500bb26986e986cf122633ffbefbb18c28f6297af5d'; Data='H4sIACxB52oC/4WPywqDMBBF9/mKge4KqXt3tpTiqoK6DkOcamBMJEmr/fs+dCGFtquBcw/3MnUgL7ElG1PYiozZjSkkQmwgywFtGMkD2dZYCiBBexwZLs4DmxsteXjeBrSJGI2zQdSrynOWy5LQ627v4qp+7Rw6jKeiki/2RSnID0yTifcfNYzXhv6vzdrH2AZKE6nHAdjp9x9iASkoVebVUakkzGQ39SweTSL+rDgBAAA=' }
  @{ Path='services'; Sha='2a1b1296625159d79e6adeb7df8a9fee2f84e4141e2fc00cc38b807d513ae4c2'; Data='' }
  @{ Path='sitemap.xml'; Sha='38340f0268e1a21e25426fccba7023122e48940b4562511b2f016c8f24a00f56'; Data='H4sIACxB52oC/62RPQ+CMBCGd35F0x0OGPwKlEkTZ3EmWBppAi3pFdB/b1Hi5gBxunvv67nLJdmjbcggDEqtUhoFISVCcV1JdU/pNT/5O5oxL+lNg8ISV6wwpbW13QFgHMcApRVt2WGgzR2Q104gzEEIgz1lHiFT+2Sd12jOiuJyzo9FAQlMck6UaFtdsTiMN34U+WHksnPsU9EZqY20T+a2TOCrpvkwA36BUJhBcoErge6OhcDypnu7mrZdSONa2ZL/m/c27uvMewGES8FFJgIAAA==' }
  @{ Path='vercel.json'; Sha='73ba366a2408184bd3c293c3a4b6edade23526df0cb90d9ad3919d20bddbf745'; Data='' }
)
function Unpack($b64) {
  $ms = New-Object System.IO.MemoryStream(,[Convert]::FromBase64String($b64))
  $gz = New-Object System.IO.Compression.GZipStream($ms, [System.IO.Compression.CompressionMode]::Decompress)
  $out = New-Object System.IO.MemoryStream
  $gz.CopyTo($out); $gz.Dispose()
  return ,$out.ToArray()
}
$utf8 = New-Object System.Text.UTF8Encoding($false)
foreach ($f in $files) {
  $dest = Join-Path $root ($f.Path -replace '/', [IO.Path]::DirectorySeparatorChar)
  $bytes = Unpack $f.Data
  $sha = [BitConverter]::ToString([Security.Cryptography.SHA256]::Create().ComputeHash($bytes)).Replace('-','').ToLower()
  if ($sha -ne $f.Sha) { throw "Checksum mismatch for $($f.Path) - the script file may be damaged. Please download it again." }
  if ($f.Path -match '\.(html|txt|xml|json|svg)$' -or $f.Path -in @('index.html','about','services','contact','legal')) {
    $text = $utf8.GetString($bytes)
    if ($text.Contains('__SITE__')) { $bytes = $utf8.GetBytes($text.Replace('__SITE__', $SiteUrl)) }
  }
  if (Test-Path $dest) {
    $bk = Join-Path $backup ($f.Path -replace '/', [IO.Path]::DirectorySeparatorChar)
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $bk) | Out-Null
    Copy-Item $dest $bk -Force
  }
  New-Item -ItemType Directory -Force -Path (Split-Path -Parent $dest) | Out-Null
  [IO.File]::WriteAllBytes($dest, $bytes)
  Write-Host ("  updated  " + $f.Path)
}
Write-Host ""
Write-Host "Done. $($files.Count) files written for $SiteUrl. Old versions are saved in: $backup" -ForegroundColor Green
if ($Push) {
  Push-Location $root
  git add -A -- . ':!_backup_before_*'
  git commit -m "Add SEO and GEO foundation: robots, sitemap, llms.txt, schema, meta tags"
  git push
  Pop-Location
} else {
  Write-Host "Next: commit and push (or run again with -Push), and Vercel will redeploy."
}
